import {allItems,category,label} from '../data.js';
import {heading,esc,target,audioButtons,toast} from '../ui.js';
import {schedule,shuffle,checkAnswer,normalize,seeded} from '../srs.js';
import {today} from '../store.js';
const view=()=>document.querySelector('#view');
async function pool(c,deck='all'){const l=c.store.lang(),custom=c.store.state().custom.filter(x=>x.language===c.language.code);let items=[...await allItems(c.language.code),...custom];if(['favorites','mistakes','added'].includes(deck))items=items.filter(x=>l[deck].includes(x.id));else if(deck==='due')items=items.filter(x=>l.cards[x.id]?.due<=Date.now());else if(deck==='custom')items=custom;else if(c.store.state().decks.some(x=>x.id===deck))items=custom.filter(x=>x.deckId===deck);else if(deck!=='all')items=await category(c.language.code,deck);c.register(items);return items;}
function recordButton(){return `<div class="record-control"><button class="button secondary" id="record">● Record yourself</button><div id="recording-playback"></div><small>Microphone recording stays in this tab. It is never uploaded.</small></div>`;}
function bindRecord(c){document.querySelector('#record')?.addEventListener('click',async e=>{const b=e.currentTarget;try{const recording=await c.audio.toggleRecord(url=>{const el=document.querySelector('#recording-playback');if(el){el.replaceChildren();const audio=document.createElement('audio');audio.controls=true;audio.src=url;el.append(audio);}b.textContent='● Record again';b.classList.remove('recording');});b.textContent=recording?'■ Stop recording':'● Record again';b.classList.toggle('recording',recording);}catch(error){c.toast(error.message||'Microphone access was declined. You can still practice aloud.');}});}
function initializeSession(c){c.sessionCleanup?.();const abort=new AbortController();c.sessionCleanup=()=>{abort.abort();c.audio.endRecording();c.audio.stop();};return abort;}
export async function flashcards(c){const abort=initializeSession(c),l=c.store.lang(),s=c.store.state().settings;const deck=c.params?.get('deck')||'all';let items=await pool(c,deck);const available=items;const learnedToday=new Set(Object.entries(l.cards).filter(([id,x])=>x.introduced&&today(new Date(x.introduced))===today()).map(([id])=>id));const due=items.filter(x=>l.cards[x.id]?.due<=Date.now()).sort((a,b)=>l.cards[a.id].due-l.cards[b.id].due).slice(0,s.reviewLimit);const fresh=shuffle(items.filter(x=>!l.cards[x.id])).slice(0,Math.max(0,s.newLimit-learnedToday.size));items=deck==='due'?due:[...due,...fresh];let index=0,flipped=false,studied=0,direction='target',started=Date.now();
function render(){if(index>=items.length){view().innerHTML=heading('A little more rooted.','Your review session is complete.')+`<section class="card exercise celebrate"><div class="large">🌿</div><h2>${studied} cards, a little stronger.</h2><p class="muted">${available.length&&!studied?'You’re caught up for this deck, or today’s limits have been reached. Change the limits in Settings to study more.':'Come back when these words are ready to see you again.'}</p><a class="button" href="#/${c.language.code}/practice">Back to practice</a></section>`;return;}const w=items[index];c.register([w]);const reverse=direction==='reverse'||direction==='mixed'&&index%2;const audioOnly=direction==='audio';view().innerHTML=heading('A little repetition. A lasting memory.','Space to flip · 1–4 to rate · swipe to flip')+`<div class="toolbar"><select id="deck" aria-label="Flashcard deck"><option value="all">All words</option>${['due','favorites','mistakes','added','custom',...new Set(available.map(x=>x.category))].map(x=>`<option value="${x}" ${deck===x?'selected':''}>${label(x)}</option>`).join('')}${c.store.state().decks.filter(x=>x.language===c.language.code).map(x=>`<option value="${esc(x.id)}" ${deck===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="direction" aria-label="Card direction"><option value="target">Target → English</option><option value="reverse" ${direction==='reverse'?'selected':''}>English → target</option><option value="audio" ${direction==='audio'?'selected':''}>Audio → target</option><option value="mixed" ${direction==='mixed'?'selected':''}>Mixed</option></select><button class="button secondary" id="shuffle">Shuffle</button></div><div class="session"><div class="session-head"><span>${index+1} / ${items.length}</span><div class="progress"><span style="width:${index/items.length*100}%"></span></div><button class="small-button" id="star" aria-label="Star this card" aria-pressed="${l.favorites.includes(w.id)}">${l.favorites.includes(w.id)?'★':'☆'}</button></div><div class="card flashcard ${flipped?'flipped':''}" id="card" role="button" tabindex="0" aria-label="${flipped?'Answer, flip to front':'Question, flip for answer'}"><span class="eyebrow">${flipped?'A LITTLE MORE TO REMEMBER':audioOnly?'LISTEN & RECALL':reverse?'HOW WOULD YOU SAY…':'A WORD TO GET TO KNOW'}</span><div class="large">${flipped?(reverse?target(w,c.language,'large'):esc(w.native)):(audioOnly?'♬':reverse?esc(w.native):target(w,c.language,'large'))}</div>${flipped?`<p>${target(w,c.language)} · ${esc(w.native)}</p>${s.transliteration&&w.transliteration?`<p class="translit">${esc(w.transliteration)}</p>`:''}${s.ipa&&w.ipa?`<p>/${esc(w.ipa)}/</p>`:''}${w.plural?`<small>Plural: ${esc(w.plural)}</small>`:''}${w.example?`<p class="notes">${esc(w.example.target)} · ${esc(w.example.native)}</p>`:''}<p class="notes">${esc(w.notes)}</p>`:'<p class="muted" style="margin-top:20px;font-size:12px">Tap to turn over</p>'}${audioButtons(w.id)}</div>${flipped?`<div class="ratings">${['Again','Hard','Good','Easy'].map((name,r)=>{const next=schedule(l.cards[w.id],r);return `<button data-rating="${r}">${name}<small>${r===0?'1 minute':next.interval+' day'+(next.interval===1?'':'s')}</small></button>`;}).join('')}</div>`:`<button class="button secondary" id="flip" style="width:100%;margin-top:18px">Turn over ↻</button>`}${recordButton()}</div>`;
 document.querySelector('#card').onclick=e=>{if(!e.target.closest('[data-audio]')){flipped=!flipped;render();}};document.querySelector('#flip')?.addEventListener('click',()=>{flipped=true;render();});document.querySelector('#deck').onchange=e=>c.go('flashcards/deck='+encodeURIComponent(e.target.value));document.querySelector('#direction').onchange=e=>{direction=e.target.value;flipped=false;render();};document.querySelector('#shuffle').onclick=()=>{items=[...items.slice(0,index),...shuffle(items.slice(index))];render();};document.querySelector('#star').onclick=()=>{l.favorites=l.favorites.includes(w.id)?l.favorites.filter(x=>x!==w.id):[...l.favorites,w.id];c.store.save();render();};for(const b of document.querySelectorAll('[data-rating]'))b.onclick=()=>rate(Number(b.dataset.rating));let x;document.querySelector('#card').addEventListener('touchstart',e=>x=e.changedTouches[0].clientX,{passive:true});document.querySelector('#card').addEventListener('touchend',e=>{if(Math.abs(e.changedTouches[0].clientX-x)>60){flipped=!flipped;render();}},{passive:true});bindRecord(c);if((s.autoplay||audioOnly)&&!flipped)c.audio.speak(w,c.language,false,c.toast);}
function rate(r){if(!flipped||!items[index])return;const w=items[index];l.cards[w.id]=schedule({...l.cards[w.id],introduced:l.cards[w.id]?.introduced||Date.now()},r);c.store.record(w.id,r>0,5,Math.min(120,(Date.now()-started)/1000));studied++;index++;started=Date.now();flipped=false;render();}
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,button'))return;if(e.code==='Space'||e.key==='Enter'&&e.target.id==='card'){e.preventDefault();flipped=!flipped;render();}if(/^[1-4]$/.test(e.key))rate(Number(e.key)-1);},{signal:abort.signal});render();return c.sessionCleanup;}
export async function quizBuilder(c){const items=await allItems(c.language.code);const cats=[...new Set(items.map(x=>x.category))];view().innerHTML=heading('Make a little challenge.','Choose your topics and the way you want to practice.')+`<form class="card settings" id="quiz-builder"><div class="grid2"><label class="field">Topic<select name="category"><option value="all">A little of everything</option>${cats.map(x=>`<option value="${x}">${label(x)}</option>`).join('')}<option value="favorites">Starred words</option><option value="mistakes">My mistakes</option><option value="custom">All custom words</option>${c.store.state().decks.filter(x=>x.language===c.language.code).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Questions<select name="count"><option>10</option><option>20</option><option>50</option></select></label><label class="field">Direction<select name="direction"><option value="target">Target → English</option><option value="reverse">English → target</option><option value="mixed">Mixed</option></select></label><label class="field">Pace<select name="timed"><option value="no">Take your time</option><option value="yes">Timed · 30 seconds per question</option></select></label></div><h3>Mix things up</h3><div class="grid2 checklist">${[['choice','Multiple choice'],['type','Type a translation'],['listen','Listen & choose'],['bank','Build a sentence'],['blank','Fill a blank'],['speak','Speaking practice'],['tf','True or false'],['scramble','Unscramble letters']].map(([id,name])=>`<label><input type="checkbox" name="types" value="${id}" checked>${name}</label>`).join('')}</div><button class="button" style="margin-top:20px">Let’s begin →</button></form>`;if(c.params?.get('deck'))document.querySelector('[name=category]').value=c.params.get('deck');document.querySelector('#quiz-builder').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),types=f.getAll('types');if(!types.length)return c.toast('Choose at least one exercise type.');startQuiz(c,{deck:f.get('category'),questionCount:Number(f.get('count')),direction:f.get('direction'),timed:f.get('timed')==='yes',types});};}
export async function startQuiz(c,options={}){const abort=initializeSession(c);const s=c.store.state(),l=c.store.lang(),random=options.daily?seeded(today()+c.language.code):Math.random;const full=options.items||await pool(c,options.deck||c.params?.get('deck')||'all');c.register(full);if(!full.length){view().innerHTML=heading('A little empty here.','Add some words to this collection, then come back to practice.')+`<a class="button" href="#/${c.language.code}/phrasebook">Explore the phrasebook</a>`;return;}let types=options.types||['choice','type','listen','bank','blank','tf','speak','scramble'];if(options.mode==='spelling')types=['type'];if(options.mode==='listening')types=['listen','type'];if(options.daily||options.placement)types=['choice','type','tf'];const count=Math.min(options.questionCount||10,Math.max(full.length,1));const queue=shuffle(full,random).slice(0,count);let index=0,correct=0,missed=[],answered=false,feedback=null,start=Date.now(),questionStart=Date.now(),intro=options.introduce?0:-1,typed='',hint=0,score=0,consecutive=0,hearts=3;let selected=[],candidate=null,choices=[],type='',expected='',reverse=false,bank=[];const limit=options.timed?count*30:0;let timer;
function header(){return `<div class="session-head"><a class="button secondary" href="#/${c.language.code}/practice" aria-label="Exit session">×</a><div class="progress"><span style="width:${index/queue.length*100}%"></span></div><small>${index+1} / ${queue.length}</small>${limit?'<span id="time-left"></span>':''}${s.settings.hearts?`<span aria-label="Hearts remaining">♥ ${hearts}</span>`:''}</div>`;}
function prepare(){answered=false;feedback=null;typed='';hint=0;selected=[];questionStart=Date.now();const w=queue[index];reverse=options.direction==='reverse'||options.direction==='mixed'&&index%2===1;expected=reverse?w.target:w.native;type=types[index%types.length];if(options.mode==='spelling'||type==='scramble'){reverse=true;expected=w.target;}if(options.mode==='listening'){reverse=true;expected=w.target;}if(type==='bank'){reverse=true;expected=w.target;bank=shuffle(expected.split(/\s+/),random);}if(type==='blank'){reverse=true;const words=w.target.split(/\s+/);expected=words[words.length-1];choices=shuffle([expected,...shuffle(full.filter(x=>x.id!==w.id),random).slice(0,3).map(x=>x.target.split(/\s+/).at(-1))],random);}
if(['choice','listen'].includes(type)){if(type==='listen'){reverse=false;expected=w.native;}const distractors=shuffle([...new Set(full.filter(x=>x.id!==w.id).map(x=>reverse?x.target:x.native))].filter(x=>x!==expected),random).slice(0,3);choices=shuffle([expected,...distractors],random);}if(type==='tf')candidate=random()>.5?w:full[Math.floor(random()*full.length)];if(type==='scramble')bank=shuffle(Array.from(expected.replace(/\s/g,'')),random);render();if(type==='listen'||options.mode==='listening')c.audio.speak(w,c.language,false,c.toast);}
function render(){if(intro>=0){const w=full[intro];view().innerHTML=`<div class="session">${header()}<div class="card exercise"><span class="eyebrow">MEET YOUR NEW WORDS · ${intro+1} / ${full.length}</span><div class="large">${target(w,c.language,'large')}</div><h2>${esc(w.native)}</h2>${w.transliteration?`<p class="muted">${esc(w.transliteration)}</p>`:''}${audioButtons(w.id)}<p class="muted">${esc(w.notes)}</p><button class="button" id="intro-next">${intro===full.length-1?'Let’s practice':'Next word'} →</button></div></div>`;document.querySelector('#intro-next').onclick=()=>{intro++;if(intro>=full.length){intro=-1;prepare();}else render();};if(s.settings.autoplay)c.audio.speak(w,c.language,false,c.toast);return;}
const w=queue[index],isInput=['type'].includes(type);const title=type==='listen'?'What did you hear?':type==='type'?(options.mode==='listening'?'Listen, then type what you hear.':'Put it into words.'):type==='bank'?'Build the translation.':type==='blank'?'Find the missing word.':type==='tf'?'Do these belong together?':type==='speak'?'Give it your voice.':type==='scramble'?'Put the letters in order.':'Choose the meaning.';const prompt=type==='listen'||options.mode==='listening'?'':type==='tf'?`${target(w,c.language,'large')}<p>${esc(candidate.native)}</p>`:type==='blank'?`<bdi dir="${c.language.direction}" class="large">${esc(w.target.split(/\s+/).slice(0,-1).join(' '))} ____</bdi><p>${esc(w.native)}</p>`:reverse?esc(w.native):target(w,c.language,'large');
let body='';if(['choice','listen','blank'].includes(type))body=`<div class="options">${choices.map((x,i)=>`<button class="option ${answered?(checkAnswer(x,expected,s.settings.strict).correct?'correct-option':x===typed?'wrong-option':''):''}" data-choice="${i}" ${answered?'disabled':''}>${esc(x)}</button>`).join('')}</div>`;else if(type==='tf')body=`<div class="options"><button class="option ${answered?(candidate.native===w.native?'correct-option':!feedback.correct?'wrong-option':''):''}" data-tf="1" ${answered?'disabled':''}>✓ True</button><button class="option ${answered?(candidate.native!==w.native?'correct-option':!feedback.correct?'wrong-option':''):''}" data-tf="0" ${answered?'disabled':''}>× False</button></div>`;else if(isInput)body=`<input class="answer-input" id="answer-input" aria-label="Your translation" dir="${reverse?c.language.direction:'ltr'}" lang="${reverse?c.language.code:'en'}" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(typed)}" ${answered?'disabled':''}>${reverse?`<div class="keybar" dir="${c.language.direction}">${c.language.keyboard.map(k=>`<button data-key="${esc(k)}" aria-label="Insert ${esc(k)}" ${answered?'disabled':''}>${esc(k)}</button>`).join('')}</div>`:''}<button class="button secondary" id="hint" ${answered?'disabled':''}>Reveal a letter (−2 XP)</button><button class="button" id="check" ${answered?'disabled':''}>Check answer</button>`;else if(['bank','scramble'].includes(type)){body=`<div class="tiles dropzone">${selected.map((n,i)=>`<button data-remove="${i}" ${answered?'disabled':''}>${esc(bank[n])}</button>`).join('')||'<small>Tap tiles to build your answer</small>'}</div><div class="tiles">${bank.map((x,i)=>`<button data-tile="${i}" ${selected.includes(i)||answered?'disabled':''}>${esc(x)}</button>`).join('')}</div><button class="button" id="check" ${answered?'disabled':''}>Check answer</button>`;}else if(type==='speak')body=`<p>Say this aloud, record it, then compare with the reference.</p>${target(w,c.language,'large')}${recordButton()}<div class="flex" style="justify-content:center;margin-top:20px">${['Nailed it','Almost','Try again'].map((x,i)=>`<button class="button secondary" data-self="${i}" ${answered?'disabled':''}>${x}</button>`).join('')}</div>`;
view().innerHTML=`<div class="session">${header()}<section class="card exercise ${feedback?(feedback.correct?'is-correct':'is-incorrect'):''}"><h2>${title}</h2><div class="large">${prompt}</div>${audioButtons(w.id)}${body}${feedback?`<div class="answer ${feedback.correct?'correct':'incorrect'}" role="status"><div class="answer-heading"><span class="answer-icon" aria-hidden="true">${feedback.correct?'✓':'×'}</span><span>${feedback.correct?'Correct!':feedback.close?'Almost — try this spelling':'Incorrect — let’s review'}</span></div>${feedback.close?`<p>You wrote “${esc(typed)}”.</p>`:''}<span class="answer-label">${feedback.correct?'You’ve got it':'Correct answer'}</span>${target(w,c.language)} · ${esc(w.native)}${feedback.double?'<br>Check the double consonants: a single or doubled consonant can change the meaning.':''}${typed&&['type','bank','scramble'].includes(type)?`<div aria-label="Character feedback">${Array.from(expected).map((ch,i)=>`<span class="${normalize(ch,s.settings.strict)===normalize(typed[i]||'',s.settings.strict)?'correct-char':'wrong-char'}">${esc(ch)}</span>`).join('')}</div>`:''}<small>${esc(w.notes)}</small></div><button class="button" id="next">${index===queue.length-1?'See how you did':'Keep going'} →</button>`:''}</section></div>`;
for(const b of document.querySelectorAll('[data-choice]'))b.onclick=()=>answer(choices[Number(b.dataset.choice)]);for(const b of document.querySelectorAll('[data-tf]'))b.onclick=()=>finish((b.dataset.tf==='1')===(candidate.native===w.native));for(const b of document.querySelectorAll('[data-self]'))b.onclick=()=>finish(Number(b.dataset.self)===0);for(const b of document.querySelectorAll('[data-tile]'))b.onclick=()=>{selected.push(Number(b.dataset.tile));render();};for(const b of document.querySelectorAll('[data-remove]'))b.onclick=()=>{selected.splice(Number(b.dataset.remove),1);render();};const input=document.querySelector('#answer-input');input?.addEventListener('input',e=>typed=e.target.value);input?.addEventListener('keydown',e=>{if(e.key==='Enter')answer(typed);});for(const b of document.querySelectorAll('[data-key]'))b.onclick=()=>{const pos=input.selectionStart??input.value.length;input.setRangeText(b.dataset.key,pos,input.selectionEnd??pos,'end');typed=input.value;input.focus();};document.querySelector('#hint')?.addEventListener('click',()=>{hint++;typed=Array.from(expected).slice(0,hint).join('');input.value=typed;input.focus();s.xp=Math.max(0,s.xp-2);c.store.save();});document.querySelector('#check')?.addEventListener('click',()=>answer(isInput?typed:selected.map(i=>bank[i]).join(type==='scramble'?'':' ')));document.querySelector('#next')?.addEventListener('click',()=>{c.audio.endRecording();index++;if(index>=queue.length||s.settings.hearts&&hearts<=0)results();else prepare();});bindRecord(c);if(input&&!answered)input.focus();}
function answer(value){typed=value;const result=checkAnswer(value,expected,s.settings.strict);finish(result.correct,result);}
function finish(ok,extra={}){if(answered)return;answered=true;const w=queue[index];feedback={...extra,correct:ok};consecutive=ok?consecutive+1:0;const xp=ok?10+(consecutive>=3?2:0):0;score+=xp;correct+=ok?1:0;if(!ok){hearts--;missed.push(w);}l.cards[w.id]=schedule({...l.cards[w.id],introduced:l.cards[w.id]?.introduced||Date.now()},ok?2:0);c.store.record(w.id,ok,xp,Math.min(120,(Date.now()-questionStart)/1000));c.audio.sound(ok);render();if(!ok)c.audio.speak(w,c.language,false,c.toast);}
function results(){clearInterval(timer);c.audio.stop();const attempted=correct+missed.length,accuracy=attempted?Math.round(correct/attempted*100):0;const passed=accuracy>=80;const seconds=Math.floor((Date.now()-start)/1000);if(options.unit&&passed){const u=l.units[options.unit]??={completed:0,mastery:0,last:0};if(options.unitTest){u.mastery=Math.min(5,u.mastery+1);u.completed=Math.max(u.completed,options.lessonCount||1);}else u.completed++;u.last=Date.now();if(options.unitTest||u.completed>=(options.lessonCount||1))l.lastUnit=Math.min(16,Math.max(l.lastUnit,options.unitIndex+1));}if(options.placement){l.placement=true;if(passed)l.lastUnit=Math.max(l.lastUnit,2);}if(accuracy===100&&attempted>=5)l.perfect=true;if(options.daily)l.challenge={date:today(),score:`${correct}/${attempted}`,seconds};c.store.save();view().innerHTML=`<div class="session"><section class="card exercise celebrate"><div class="large">${passed?'🌿':'🌱'}</div><span class="eyebrow">A LITTLE PRACTICE, WELL SPENT</span><h1>${passed?'Look at you growing.':'Every attempt is a step forward.'}</h1><div class="stats-row"><div class="stat"><div><strong>${score}</strong><small>XP earned</small></div></div><div class="stat"><div><strong>${accuracy}%</strong><small>Accuracy · ${correct}/${attempted}</small></div></div><div class="stat"><div><strong>${seconds}s</strong><small>Time practiced</small></div></div></div><p class="muted" style="margin-top:20px">${options.unit?(passed?'Progress saved. Your next little adventure is ready.':'Reach 80% to complete this lesson. You can practice these words again.'):'Your progress has been saved on this device.'}</p><div class="flex" style="justify-content:center"><a class="button" href="#/${c.language.code}/${options.unit?'learn':'practice'}">Keep exploring →</a>${missed.length?'<button class="button secondary" id="retry-mistakes">Practice these mistakes</button>':''}${options.daily?'<button class="button secondary" id="challenge-score">Export challenge score</button>':''}</div>${missed.length?`<h3 style="margin-top:30px">A few words to revisit</h3>${missed.map(w=>`<p>${target(w,c.language)} · ${esc(w.native)} ${audioButtons(w.id)}</p>`).join('')}`:'<p style="margin-top:25px">✦ A perfect little session.</p>'}</section></div>`;document.querySelector('#retry-mistakes')?.addEventListener('click',()=>startQuiz(c,{items:[...new Map(missed.map(x=>[x.id,x])).values()],types:['choice','type']}));document.querySelector('#challenge-score')?.addEventListener('click',()=>c.store.download('parola-challenge.txt',`Parola daily challenge · ${today()} · ${c.language.name}\n${correct}/${attempted} · ${seconds} seconds`,'text/plain'));}
if(limit){timer=setInterval(()=>{const left=Math.max(0,limit-Math.floor((Date.now()-start)/1000));const el=document.querySelector('#time-left');if(el)el.textContent=left+'s';if(!left){if(!answered)finish(false);results();}},1000);const previous=c.sessionCleanup;c.sessionCleanup=()=>{clearInterval(timer);previous();};}if(intro>=0)render();else prepare();return c.sessionCleanup;}
export async function match(c){const abort=initializeSession(c),items=await pool(c,c.params?.get('deck')||'all');if(items.length<2){view().innerHTML=heading('A few more words first.','This game needs at least two words.');return;}const chosen=shuffle(items).slice(0,6),tiles=shuffle(chosen.flatMap((x,i)=>[{id:x.id,text:x.target,side:0,i},{id:x.id,text:x.native,side:1,i}]));let first=null,matched=[],busy=false,mistakes=0;const start=Date.now();view().innerHTML=heading('Find a little connection.','Match each word with its English meaning. Your timer is running.')+`<div class="session"><div class="flex between"><p id="match-time">0 seconds</p><p class="muted">Best: ${c.store.lang().bestMatch??'—'} seconds</p></div><div class="matching">${tiles.map((x,i)=>`<button data-pair="${i}" ${x.side===0?`dir="${c.language.direction}" lang="${c.language.code}"`:''}>${esc(x.text)}</button>`).join('')}</div><div id="match-result"></div></div>`;const timer=setInterval(()=>{const el=document.querySelector('#match-time');if(el)el.textContent=Math.floor((Date.now()-start)/1000)+' seconds';},1000);const prev=c.sessionCleanup;c.sessionCleanup=()=>{clearInterval(timer);prev();};for(const b of document.querySelectorAll('[data-pair]'))b.onclick=()=>{if(busy||matched.includes(Number(b.dataset.pair)))return;const i=Number(b.dataset.pair);if(i===first)return;b.classList.add('selected');if(first===null){first=i;return;}const old=first;first=null;if(tiles[i].id===tiles[old].id&&tiles[i].side!==tiles[old].side){matched.push(i,old);b.classList.remove('selected');document.querySelector(`[data-pair="${old}"]`).classList.remove('selected');b.classList.add('matched');document.querySelector(`[data-pair="${old}"]`).classList.add('matched');c.store.record(tiles[i].id,true,5,(Date.now()-start)/1000/chosen.length);c.audio.sound(true);if(matched.length===tiles.length){clearInterval(timer);const seconds=Math.floor((Date.now()-start)/1000);const l=c.store.lang();l.bestMatch=Math.min(l.bestMatch??Infinity,seconds);c.store.save();document.querySelector('#match-result').innerHTML=`<div class="answer celebrate">✓ All connected! ${seconds} seconds · ${mistakes} missed pairs<br><button id="match-again" class="button secondary">Play again</button></div>`;document.querySelector('#match-again').onclick=()=>match(c);}}else{mistakes++;busy=true;b.classList.add('mismatch');document.querySelector(`[data-pair="${old}"]`).classList.add('mismatch');c.audio.sound(false);c.store.record(tiles[i].id,false,0);setTimeout(()=>{b.classList.remove('selected','mismatch');document.querySelector(`[data-pair="${old}"]`)?.classList.remove('selected','mismatch');busy=false;},650);}};return c.sessionCleanup;}
